effect.shader:
const int MAXIMO_DE_AMOSTRAS = 16;

/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

float hash1(vec2 c) {
    return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
    vec2 tam = vec2(textureSize(inputImg, 0));
    vec2 px = 1.0 / tam;

    vec4 original = texture(inputImg, acScreenNorm);

    // Gradiente da luma por diferenças centrais: ∂L/∂x = (L(x+1) - L(x-1)) / 2.
    float lx = luma(texture(inputImg, acScreenNorm + vec2(px.x, 0.0)).rgb)
             - luma(texture(inputImg, acScreenNorm - vec2(px.x, 0.0)).rgb);
    float ly = luma(texture(inputImg, acScreenNorm + vec2(0.0, px.y)).rgb)
             - luma(texture(inputImg, acScreenNorm - vec2(0.0, px.y)).rgb);

    // Tangente = perpendicular ao gradiente. Uma área lisa (gradiente ~0) ganha uma
    // direção padrão (horizontal) para o traço não desaparecer.
    vec2 tangente = vec2(-ly, lx);
    float magnitude = length(tangente);
    tangente = magnitude > 1e-4 ? tangente / magnitude : vec2(1.0, 0.0);

    // Ruído por pixel: rotaciona o traço angleJitter graus para cada lado.
    float semente = hash1(floor(acScreenNorm * tam / max(strokeLength, 1.0)));
    float giro = radians((semente * 2.0 - 1.0) * angleJitter);
    float cosG = cos(giro);
    float sinG = sin(giro);
    vec2 t = vec2(tangente.x * cosG - tangente.y * sinG, tangente.x * sinG + tangente.y * cosG);

    int n = clamp(int(detail + 0.5), 2, MAXIMO_DE_AMOSTRAS);
    int metade = n / 2;

    // Média ao longo da tangente — isso é o "borrão direcional" que pinta o traço.
    vec3 soma = vec3(0.0);
    float peso = 0.0;
    for (int i = -MAXIMO_DE_AMOSTRAS / 2; i <= MAXIMO_DE_AMOSTRAS / 2; i++) {
        if (i < -metade || i > metade) continue;
        float f = float(i) / float(metade);
        vec2 deslocamento = t * f * strokeLength * px;
        vec3 c = texture(inputImg, acScreenNorm + deslocamento).rgb;
        // Peso triangular: as pontas pesam menos, o miolo do traço mais.
        float w = 1.0 - abs(f);
        soma += c * w;
        peso += w;
    }
    vec3 pintado = soma / max(peso, 1e-4);

    vec3 cor = mix(original.rgb, pintado, strength);
    fragColor = vec4(cor, original.a);
}
